// ===========================================================================
// 26355 THE NEAR-CLASS CENSUS (pure gauge; full ledger at KH_BUILD_TAG).
//
// The rotation capture pair proved the footprint encodes with the wrong near
// plane (0.64264 where the correct frame had 0.07000, same spot, same box,
// same far). The obvious repair was to lock the encode to the WORLD's near,
// and the obvious way to find that value was frequency: the world near arrives
// as a hard exact repeat while foreign values looked like smooth continua.
// THAT DISCRIMINATOR IS FALSIFIED, and it was falsified by replaying the
// tracker over the real populations BEFORE anything shipped. Every window has
// a constant near, not just the world's:
//     dump1: 0.0700 x48, 0.7891 x35, 0.2503 x25
//     dump2: 0.2503 x113, 0.3491 x16, 0.0700 x14
// On dump2 a mode-finder picks 0.2503 and on dump1 it does not converge at
// all. Frequency cannot separate these, so no lock ships this build - shipping
// one would have encoded the wrong constant with total confidence, which is
// 26326 wearing a new coat.
//
// What ships instead is the census itself, so the next dump reports the whole
// population per session instead of one summary statistic. Misra-Gries over 8
// slots, counts halved every KH_NB_DECAY notes so a changed world near takes
// over in seconds. PURE OBSERVER: nothing reads it.
// ===========================================================================
static constexpr int      KH_NB_SLOTS = 8;
static constexpr uint32_t KH_NB_DECAY = 4096;
static int32_t  g_nb_key[KH_NB_SLOTS] = {};     // near * 10000; 0 = empty
static uint32_t g_nb_cnt[KH_NB_SLOTS] = {};
static uint32_t g_nb_notes = 0;

inline void kh_near_base_note(float khnb_v) {
    // Sanity only - anything outside this cannot be a near plane at all.
    if (!(khnb_v > 0.001f && khnb_v < 20.0f)) return;

    const int32_t khnb_k = static_cast<int32_t>(khnb_v * 10000.0f + 0.5f);
    int khnb_hit = -1, khnb_free = -1, khnb_min = 0;

    for (int i = 0; i < KH_NB_SLOTS; ++i) {
        if (g_nb_key[i] == khnb_k) { khnb_hit = i; break; }
        if (g_nb_key[i] == 0 && khnb_free < 0) khnb_free = i;
        if (g_nb_cnt[i] < g_nb_cnt[khnb_min]) khnb_min = i;
    }

    if (khnb_hit >= 0) {
        if (g_nb_cnt[khnb_hit] < 0x40000000u) g_nb_cnt[khnb_hit]++;
    } else if (khnb_free >= 0) {
        g_nb_key[khnb_free] = khnb_k; g_nb_cnt[khnb_free] = 1;
    } else if (g_nb_cnt[khnb_min] == 0) {
        g_nb_key[khnb_min] = khnb_k; g_nb_cnt[khnb_min] = 1;
    } else {
        for (int i = 0; i < KH_NB_SLOTS; ++i) if (g_nb_cnt[i]) g_nb_cnt[i]--;
    }

    if (++g_nb_notes >= KH_NB_DECAY) {
        g_nb_notes = 0;
        for (int i = 0; i < KH_NB_SLOTS; ++i) {
            g_nb_cnt[i] >>= 1;
            if (g_nb_cnt[i] == 0) g_nb_key[i] = 0;
        }
    }
}

// Slot i of the census, ordered by count, for the dump. Returns the near in
// metres (0 = empty) and writes its vote count.
inline float kh_near_class(int khnc_i, uint64_t* khnc_votes) {
    int khnc_ord[KH_NB_SLOTS];
    for (int i = 0; i < KH_NB_SLOTS; ++i) khnc_ord[i] = i;
    for (int a = 0; a < KH_NB_SLOTS; ++a)
        for (int b = a + 1; b < KH_NB_SLOTS; ++b)
            if (g_nb_cnt[khnc_ord[b]] > g_nb_cnt[khnc_ord[a]]) {
                const int sw = khnc_ord[a]; khnc_ord[a] = khnc_ord[b]; khnc_ord[b] = sw;
            }
    if (khnc_i < 0 || khnc_i >= KH_NB_SLOTS) { if (khnc_votes) *khnc_votes = 0; return 0.0f; }
    const int khnc_s = khnc_ord[khnc_i];
    if (khnc_votes) *khnc_votes = g_nb_cnt[khnc_s];
    return static_cast<float>(g_nb_key[khnc_s]) * 1.0e-4f;
}
