static float    g_svs_eng_ver_len = -1.0f;           // last verified residuals
static float    g_svs_eng_ver_wcol = -1.0f;
static float    g_svs_eng_ver_row3 = -1.0f;
static float    g_svs_eng_ver_wcol_max = 0.0f;       // worst seen on a FAILING frame
static float    g_svs_eng_ver_row3_max = 0.0f;
