static float    g_svs_eng_ref_rot[9] = {};      // CPU view 3x3 stashed at the copy
static float    g_svs_eng_ref_rot_pend[9] = {};
static bool     g_svs_eng_ref_valid = false;
static bool     g_svs_eng_ref_pend_valid = false;
static float    g_svs_eng_ver_rot_deg = -1.0f;
static float    g_svs_eng_ver_rot_max_deg = 0.0f;
