static constexpr uint32_t KH_SVS_ENG_SWEEP_MAX      = 32u;   // attempts per frame, unlocated
static constexpr uint32_t KH_SVS_ENG_RECONFIRM_DIV  = 512u;  // slow rate once located
static constexpr uint32_t KH_SVS_ENG_RECONFIRM_MAX  = 2u;
static uint32_t g_svs_eng_sweep_ctr = 0;           // draw divider
static uint32_t g_svs_eng_sweep_frame = 0;         // attempts this frame (boundary reset)
static uint32_t g_svs_eng_sweep_frame_max = 0;     // peak
