                        const float khlt_stl = khlt_bm == 221 ? 0.02f : 0.005f;
                        const bool  khlt_still = khlt_ref < khlt_stl;
                        const float khlt_ratio_b = khlt_mul * khlt_ref;
                        const float khlt_bnd =
                            (khlt_bm == 157 || khlt_bm == 196)
                                ? (khlt_ratio_b > 0.30f ? khlt_ratio_b : 0.30f)
                                : (khlt_still ? 0.30f
                                              : (khlt_ratio_b > 0.30f ? khlt_ratio_b : 0.30f));

