// FULL SESSION DESTROY (operator requirement): everything learned,
// published, staged, counted or derived dies with the mission - the next
// mission starts from the same nothing a fresh process would. Device
// objects and locator/probe state go through release_shadow_device_state()
// + g_res.release() (the caller runs those first, under the graphics lock);
// this resets what those don't. Must run with the render thread PARKED:
// g_ro, the mask/live structs and the hoisted memories are render-thread
// state.
inline void reset_session_state() {
    reset_stat_counters();
    kh_ui_mask_reset();   // 26055: learned backbuffers, phase machine, demand flag
    g_kh_track_wanted.store(false, std::memory_order_relaxed);   // 26064: recomputes
                                                                 // at the next flush
    g_sun_pub_prev_valid = false;   // the settle tracker restarts with the session
    g_sun_unstable_ms = 0;
    g_sun_valid_ms = 0;
    g_sun_last_jump_ms = 0;
    g_sun_pub_travel_ref[0] = g_sun_pub_travel_ref[1] = g_sun_pub_travel_ref[2] = 0.0f;
    g_sun_pub_travel_ref_ms = 0;   // publish-travel detector restarts with the session
    g_sun_pub_travel_ms = 0;
    g_sun_jump_rate_refused = 0;
    g_sun_fell_ms = 0;
    g_sun_ok_prev = false;
    g_stats_armed.store(false, std::memory_order_relaxed);
    g_diag_armed.store(false, std::memory_order_relaxed);   // recorder re-arms on demand
    g_dbg_mode.store(0, std::memory_order_relaxed);         // debug visuals off

    {   // error dedupe dies with the session (a fresh session re-reports)
        std::lock_guard<std::mutex> g(g_err_once_mutex);
        g_err_once.clear();
    }

    // KH_JITTER_FLOOR continuity: a new session is a new camera, so the
    // previous frame's is not a predecessor. Dropping it here (and NOT at
    // the stats arm) is the difference between one skipped sample and one
    // fabricated hold.
    g_jit_prev_valid = false;
    g_jit_hold_run = 0;

    // the lifetime pairing trio is session-scoped under full destroy
    g_view_relock_forced = 0; g_lock_wipes = 0; g_ls.view_locks = 0;
    g_lock_churn_ms_v = 0;   // lock-settle: a fresh session starts unheld
    g_cast_ready = false;    // readiness latch: a fresh session re-dwells
    g_cast_ready_since_ms = 0;
    g_cast_ready_ms = 0;
    g_cast_ready_t = -1.0f;
    g_sun_snap_cand[0] = g_sun_snap_cand[1] = g_sun_snap_cand[2] = 0.0f;
    g_sun_snap_hold = 0;
    g_first_sun_valid_t = -1.0f; g_first_sun_settled_t = -1.0f;
    g_first_derived120_t = -1.0f; g_first_bandcap_t = -1.0f;
    g_recv_health_ok = false; g_recv_health_since_ms = 0; g_recv_health_t = -1.0f;
    g_sun_map_mature_pub = -1.0f;
    g_first_livelatch_t = -1.0f;   // cold timeline restarts with the session
    g_first_sun_boot_t = -1.0f;    // 26133: bootstrap stamp rides the same restart
    g_view_adopts = 0; g_view_adopt_stale = 0; g_view_adopt_family = 0;
    g_view_adopt_last_rot = 0.0f; g_view_adopt_max_rot = 0.0f;
    g_ls.view_relocks = 0;
    g_ls.pub_rej_streak = 0; g_ls.view_src_miss = 0;
    g_ls.last_publish_rot_err = 1.0f;
    g_ls.pub_exact_ms = 0;
    g_ls.pub_any_ms = 0;
    g_ls.pub_fresh_ms = 0;
    g_lit_gate_since_ms = 0;
    g_lit_gate_pub = 0;   // round-13: the published verdict dies with the session
    g_ls.view_best_rot = -1.0f; g_ls.view_best_trans = -1.0f;
    g_ls.cam[0] = g_ls.cam[1] = g_ls.cam[2] = 0.0f;
    g_ls.stamp_counter = 0;
    // published / staged / derived lighting and its debounce latch
    g_sun_valid = false;
    g_sun_dir_engine[0] = 0.0f; g_sun_dir_engine[1] = 1.0f; g_sun_dir_engine[2] = 0.0f;
    g_sun_dir_derived_valid = false;
    g_sun_dir_derived[0] = 0.0f; g_sun_dir_derived[1] = 1.0f; g_sun_dir_derived[2] = 0.0f;
    g_sun_derived_samples = 0;
    g_sun_jump_pending = false;
    g_skysun_ref_valid = false;
    g_skysun_ref[0] = g_skysun_ref[1] = g_skysun_ref[2] = 0.0f;
    g_skysun_ref_ms = 0;
    g_skysun_mot_ref_ms = 0; g_skysun_mot_deg = -1.0f;
    g_pub_valid = false; g_cand_hold = 0;
    g_pub_boot = false;   // 26133: bootstrap era dies with the publish
    g_fog_staged_valid = false; g_fog_valid = false;

    for (int k = 0; k < 3; ++k) { g_fog[k] = 0.0f; g_fog_staged[k] = 0.0f; }

    // hoisted lock memories
    g_pub_first = -1.0f;
    g_pub_block_valid = false;
    g_pub_block_amb[0] = g_pub_block_amb[1] = g_pub_block_amb[2] = 0.0f;
    g_pub_block_sun[0] = g_pub_block_sun[1] = g_pub_block_sun[2] = 0.0f;
    g_pub_block_fog[0] = g_pub_block_fog[1] = g_pub_block_fog[2] = 0.0f;
    g_blk_pend_amb_l = -1.0f; g_blk_pend_sun_l = -1.0f; g_blk_pend_ms = 0;
    // 26495: the injection snapshot + continuity ring survived missions -
    // old-mission lighting flavors biased the new mission's first ~1 s
    // (bounded, but a reset must reproduce cold start exactly). Ring
    // counters die with the mission like the rest of the session lanes.
    g_inj_blk_amb[0] = g_inj_blk_amb[1] = g_inj_blk_amb[2] = -1.0f;
    g_inj_blk_sun[0] = g_inj_blk_sun[1] = g_inj_blk_sun[2] = -1.0f;
    g_inj_blk_ms = 0;
    memset(g_blk_ring, 0, sizeof(g_blk_ring));
    g_blk_ring_next = 0; g_blk_ring_count = 0;
    g_blk_ring_picks = 0; g_blk_snap_adopts = 0; g_blk_snap_rejects = 0;
    g_blk_ring_band_filtered = 0; g_blk_ring_no_band = 0;   // 26501
    g_blk_ring_starve_holds = 0;   // 26502
    g_blk_pub_slews = 0;   // 26503
    g_blk_slew_regime_commits = 0;   // 26611
    g_kh_sunvp_span[0] = g_kh_sunvp_span[1] = g_kh_sunvp_span[2] = -1.f;   // 26505 (26504 lanes: reset was missing)
    g_kh_sunvp_latches = 0;      // 26505
    g_kh_sunvp_fit_grows = 0;    // 26505
    g_prewarm_cand_res = nullptr; g_prewarm_cand_off = 0;
    g_coldlock_cand_res = nullptr; g_coldlock_cand_off = 0;
    g_last_pv_ms = 0;
    g_cc_flush_opaques.store(0xFFFFFFFFu, std::memory_order_relaxed);
    g_slot_keep_m22 = 0.0f; g_slot_keep_m32 = 0.0f;
    g_slot_keep_near = -1.0f; g_slot_keep_ms = 0;
    g_latch_cam_valid = false;
    g_latch_cam[0] = g_latch_cam[1] = g_latch_cam[2] = 0.0f;
    g_latch_accept_ms = 0;
    g_latch_ring_n = 0; g_latch_ring_w = 0;
    // render-thread cycle state (the caller's graphics lock parks that thread)
    // Hook DISARM: with the tracked context cleared, every installed hook
    // bails at its very first pointer compare on every context - the whole
    // pipeline is a single relaxed load per call until the next render
    // command re-stores the context via ensure_reorder_hook.
    g_reorder_target_ctx.store(nullptr, std::memory_order_relaxed);
    g_ro = ReorderState{};
    g_rescue_frame_count = 0;
    g_atlas_frame_cur = false; g_atlas_frame_prev = false;
    g_pack_on_last = 0;
    // Flight recorder dies with the session; the serial restart keeps
    // dump epochs unambiguous across missions.
    memset(g_ffr, 0, sizeof(g_ffr));
    g_ffr_head = 0; g_ffr_serial = 0;
    memset(g_ffr_snap, 0, sizeof(g_ffr_snap));
    g_ffr_lockfails.store(0, std::memory_order_relaxed);
    // Dynamic lights: mirror, censuses and ring die with the session;
    // the MODE persists at 3 - the finalized default (lit objects
    // receive the engine's dynamic lights automatically; the derivation
    // needs no operator setup, and a dark-safe failure posture - the
    // degeneracy rule + range backstop - is what made default-on
    // responsible).
    g_dl_mode.store(3, std::memory_order_relaxed);
    g_dl_intensity_bits.store(0x3F800000u, std::memory_order_relaxed);
    g_dl_recon.store(false, std::memory_order_relaxed);
    g_dl_census_on.store(false, std::memory_order_relaxed);
    dynlights_reset_session();
    g_ffr_any_eligible.store(false, std::memory_order_relaxed);
    g_ffr_dark_frames = 0; g_ffr_dark_ms = 0;
    g_ffr_erased_frames = 0; g_ffr_erased_ms = 0;
    g_composite_rescues = 0; g_rescue_last_ms = 0; g_rescue_cap_stops = 0;
    g_rescue_ref_carried = 0; g_rescue_ref_preflush = 0; g_rescue_ref_shield = 0;
    g_flush_slot_band_rejects = 0; g_flush_slot_rej_near = -1.0f;
    g_inj_enc_m22 = 0.0f; g_inj_enc_m32 = 0.0f; g_inj_enc_near = -1.0f; g_inj_enc_ms = 0;
    // 26304: the fallback's base and the baseline tracker die with the
    // session (the 26303 function-statics survived mission changes).
    g_khpe_p1 = -1.0f; g_khpe_p2 = -1.0f; g_khpe_m22 = 0.0f;
    g_khpe_ms = 0; g_khpe_upd_ms = 0; g_khpe_skip1 = -1.0f;
    g_khbl_stable = -1.0f; g_khbl_prev = -1.0f;
    g_khlt_prev_ok = false; g_khlt_prev_step = 0.0f;   // 26306: the bound's
    g_khlt_lp_ok = false;                              // 26309: the anchor's
    g_khlt_ref_ok = false; g_khlt_vc_valid = false;    // state dies too
    g_far_keep_m22 = 0.0f; g_far_keep_m32 = 0.0f; g_far_keep_far = -1.0f; g_far_keep_ms = 0;
    g_inj_slot_band_rejects = 0; g_inj_slot_rej_near = -1.0f;
    g_inj_enc_ovr_vetoes = 0; g_inj_enc_ovr_veto_near = -1.0f;   // 26314
    g_world_latch_wits = 0;                                       // 26314
    g_prb_copies = 0; g_prb_maps = 0; g_prb_busy = 0; g_prb_skips = 0;   // 26315
    g_svs_vol_copy_held = 0;                                              // 26324
    kh_prb_release();                                             // 26315
    kh_vpx_release();                                             // 26328
    g_latch_holds = 0; g_latch_hold_dist = -1.0f; g_latch_jump_adopts = 0;
    // 26109: fx depth-pair guard - census AND pair latch both fall at
    // session teardown (the g_far_keep / g_inj_enc pattern above).
    g_khfx_pair_holds = 0; g_khfx_pair_jump_adopts = 0; g_khfx_bridge_adopts = 0;
    g_khfx_confirm_vetoes = 0;   // 26113
    g_khfx_pair_near = -1.0f; g_khfx_cand_near = -1.0f; g_khfx_pair_ms = 0;
    g_khfx_verdict_serial = ~0ull; g_khfx_verdict_held = false;
    g_boundary_pv_valid = false;   // session teardown: no stale cross-mission sample
    g_boundary_t = -1.0f;
    g_live_near_ref = -1.0f; g_live_ref_m22 = 0.0f; g_live_ref_m32 = 0.0f;
    g_live_ref_ms = 0; g_live_near_pend = -1.0f; g_live_pend_ms = 0;
    g_carry_pending_serial.store(0, std::memory_order_relaxed);
    g_sr = ShadowReconState{};
    g_reorder_render_tid.store(0, std::memory_order_relaxed);
    g_main_depth_w = 0; g_main_depth_h = 0; g_wrong_pass_streak = 0;
    g_proj_last_m32 = 0.0f;
    g_mask = ShadowMaskState{};   // device pointers already nulled by the release
    g_trig_rej_vp[0] = g_trig_rej_vp[1] = -1.0f;
    g_trig_acc_vp[0] = g_trig_acc_vp[1] = -1.0f;
    g_fog_dbg[0] = g_fog_dbg[1] = g_fog_dbg[2] = g_fog_dbg[3] = 0.0f;
    g_proj_locator_ever = false;
    g_comp_fail_streak = 0; g_comp_next_retry = 0.0f; g_comp_last_err.clear();
    // Occlusion campaign residue: snapshot identity + heightfield die
    // with the mission (device objects went with g_res.release()); the
    // auto-builder simply runs again next mission.
    g_snap_serial = 0; g_snap_ms = 0;
    g_snap_pair_src = 0; g_snap_cam_valid = false;   // 26540
    g_snap_vp_valid = false;   // 26541
    g_thm_data.clear();
    g_thm_data.shrink_to_fit();
    g_thm_w = g_thm_h = 0;
    g_thm_origin[0] = g_thm_origin[1] = 0.0f;
    g_thm_cell = 0.0f;
    g_thm_filled = 0;
    g_thm_dirty = false;
    g_thm_valid = false;
    g_thml_origin[0] = g_thml_origin[1] = 0.0f;
    g_thml_cell = 0.0f;
    g_thml_w = g_thml_h = 0;
    g_thm_auto_state = 0;
    g_thm_auto_src = 0;
    g_thm_auto_cursor = 0;
    g_thm_auto_retry = 0;
    g_thmf_dim = 0;
    g_thmf_cell = 0.0f;
    // 26548: the fog below-layer sentinels die with the session (the
    // 26534/26535/26536 state survived mission changes and made the
    // arming lanes lie on the first post-change dump - the banked debt).
    g_fog_below_clamp_y = 1.0e9f;
    g_fog_below_ext = -1.0f;
    g_fog_uw_col[0] = g_fog_uw_col[1] = g_fog_uw_col[2] = -1.0f;
}

inline void reset_retained_state() {
    {
        std::lock_guard<std::mutex> g(g_draw_list_mutex);
        g_draw_list.clear();
        g_next_seq = 0;   // creation order restarts with the list it orders
    }

    g_query_pending = false;
    g_query_points_pending.clear();
    g_async_inflight_count[0] = 0;
    g_async_inflight_count[1] = 0;
    g_vis_result_count = 0;
}

inline void on_mission_start() {
    // NOTHING ACTIVATES HERE (operator requirement: state stays dead until
    // a command demands it). Draw3D registers at the first addRender3D /
    // addPostFX; the UI overlay driver registers at the first UI-phase
    // demand (affectUI pass or flushUIRender). This only clears leftovers.
    g_draw3d_eh_active = false;
    g_draw3d_eh = {};
    g_ui_driver_registered = false;
    g_ui_ctrl_created = false;
    g_ui_poll_eh = {};
    reset_retained_state();
}

inline void on_mission_end() {
    // 26495: capture the armed mode BEFORE reset_session_state clears it -
    // mode 289 reverts this build's teardown ordering + deferral to 26494.
    const bool khme_legacy = g_dbg_mode.load(std::memory_order_relaxed) == 289;
    bool khme_done = false;
    g_draw3d_eh_active = false;
    g_draw3d_eh = {};
    g_ui_driver_registered = false;
    g_ui_ctrl_created = false;
    g_ui_poll_eh = {};
    reset_retained_state();

    // FULL SESSION DESTROY: device objects, learned locations, probes,
    // mirrors, published lighting, stats - everything - dies with the
    // mission. The render thread must be PARKED before device objects and
    // render-thread state are touched; the graphics lock is that
    // invariant. The draw list is already empty, so the injection is a
    // no-op even before the lock lands - a transiently contended lock only
    // delays the release by a retry. The vtable hooks stay installed
    // (uninstalling live draw hooks is the one genuinely dangerous
    // teardown; disarmed they cost a pointer compare per draw) - but
    // everything they FEED is destroyed, and nothing re-arms until a
    // command re-creates work.
    // 26495 EARLY DISARM (289 reverts to the 26494 order): the graphics
    // lock parks only the RENDER thread, but the scene thread has ridden
    // the hooks off-thread since 26482/26489 - the 26494 success path
    // released band/atlas COM objects with admission still OPEN on that
    // thread (destroy ran before reset_session_state's ctx null). Cheap
    // relaxed stores close every hook at its entry compare on ANY thread
    // before an object is touched. This closes ADMISSION, not in-flight
    // bodies: a scene-thread hook already past its compare remains a
    // microsecond-scale window (vs the whole destroy at 26494); zeroing
    // it is an epoch/refcount design round, not a patch - ledgered.
    if (!khme_legacy) {
        g_reorder_target_ctx.store(nullptr, std::memory_order_relaxed);
        g_kh_track_wanted.store(false, std::memory_order_relaxed);
    }

    for (int attempt = 0; attempt < 8; ++attempt) {
        RVExtBridge::ScopedGraphicsLock lock;

        if (!lock.acquired()) continue;
        release_shadow_device_state();
        g_res.release();
        kh_tex_cache_release();   // material-texture SRVs are device objects too:
                                  // the next mission re-resolves through the same
                                  // cold first-bind path a fresh process would
        kh_user_shader_cache_release();   // user .hlsl shaders follow the same
                                          // doctrine: recompiles come from disk
        kh_user_lut_cache_release();      // user .cube LUTs: same doctrine
                                          // (reloads come from disk)
        kh_shader_mt_shutdown();   // 26636: no worker may outlive a mission
        reset_session_state();
        khme_done = true;   // 26495: exhaustion is counted + deferred below
        break;
    }

    // Retry-exhaustion backstop (26495; 289 reverts to the 26494 SKIP):
    // previously the destroy silently never ran - the old mission's
    // standing/anchor lighting arbitration, held atlas, view lock,
    // locators and staged sun survived ARMED into the next mission with
    // no witness anywhere; "technically clean" was conditional on a lock
    // acquisition that could fail 8 times unseen. Now exhaustion COUNTS
    // (missionResetFails, both arms) and the full destroy DEFERS to the
    // next flush's own locked body (g_mission_destroy_pending, consumed
    // at flush_frame's lock head). Draw3D - the flush driver - dies with
    // this mission, so "next flush" is the next mission's first render
    // command: exactly before any new session state matters. A mission
    // that never uses the extension holds the state DISARMED (bounded;
    // strictly better than 26494's armed inheritance).
    if (!khme_done) {
        g_mission_reset_fails++;
        if (!khme_legacy) g_mission_destroy_pending.store(true, std::memory_order_relaxed);
    }
    // Idempotent on the success path (reset_session_state already stored
    // the null); on exhaustion this is the immediate cheap disarm, and
    // under 289 it is the whole backstop - the 26494 behavior verbatim.
    g_reorder_target_ctx.store(nullptr, std::memory_order_relaxed);
}

// ===========================================================================
// Retained-mode API (called by the SQF wrappers)
// ===========================================================================

inline std::string add_render_object(const RenderObject& obj) {
    ensure_draw_eh();
    // 26064: cover the spawn frame - the per-frame recompute in
    // flush_frame arms next flush; this store arms the hooks NOW.
    g_kh_track_wanted.store(true, std::memory_order_relaxed);
    // Flight recorder: a just-added eligible mesh must count for the dark
    // tripwire even if the next flush skips before its snapshot runs.
    if (is_composite_eligible(obj)) g_ffr_any_eligible.store(true, std::memory_order_relaxed);
    std::lock_guard<std::mutex> g(g_draw_list_mutex);
    const std::string handle = make_render_uid();
    RenderObject& stored = g_draw_list[handle];
    stored = obj;
    stored.seq = ++g_next_seq;   // creation order (fullscreen pass chaining)
    stored.birth_time = effect_time_seconds();
    return handle;
}

inline bool remove_render_object(const std::string& handle) {
    std::lock_guard<std::mutex> g(g_draw_list_mutex);
    return g_draw_list.erase(handle) > 0;
}

inline size_t clear_render_objects() {
    std::lock_guard<std::mutex> g(g_draw_list_mutex);
    const size_t n = g_draw_list.size();
    g_draw_list.clear();
    return n;
}

